package trust_test

import (
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"
	"time"

	"github.com/qtorb/rosmarops/internal/exposure"
	"github.com/qtorb/rosmarops/internal/graph"
	"github.com/qtorb/rosmarops/internal/knowledge"
)

// BV-208 pt5 (CTO-26 §6): exposure-potential.json, generated by
// TestExposurePotential next to factory-scores.json. Only ids, enums and
// numbers — no user-facing prose. «Sin datos» is level null with a no_data
// reason, never 0. Field order here IS the file's key order.

type epAxis struct {
	Level  *int     `json:"level"`
	Inputs []string `json:"inputs,omitempty"`
	NoData string   `json:"no_data,omitempty"`
}

type epAxes struct {
	Autonomy   epAxis `json:"autonomy"`
	Reach      epAxis `json:"reach"`
	Contagion  epAxis `json:"contagion"`
	Delegation epAxis `json:"delegation"`
	Opacity    epAxis `json:"opacity"`
	Complexity epAxis `json:"complexity"`
}

type epAgent struct {
	Product     string   `json:"product"`
	Evaluated   bool     `json:"evaluated"`
	Axes        epAxes   `json:"axes"`
	Class       string   `json:"class,omitempty"`
	ClassStatus string   `json:"class_status,omitempty"`
	MissingAxes []string `json:"missing_axes"`
	FactoryBand string   `json:"factory_band"`
}

type epWeights struct {
	Autonomy   int `json:"autonomy"`
	Reach      int `json:"reach"`
	Contagion  int `json:"contagion"`
	Delegation int `json:"delegation"`
	Opacity    int `json:"opacity"`
	Complexity int `json:"complexity"`
}

type exposurePotential struct {
	Format                  string    `json:"format"`
	RosmaropsVersion        string    `json:"rosmarops_version"`
	Commit                  string    `json:"commit"`
	GeneratedAt             string    `json:"generated_at"`
	ReferenceComputer       string    `json:"reference_computer"`
	ContagionComputer       string    `json:"contagion_computer"`
	ContagionComputerSource string    `json:"contagion_computer_source"`
	RulesVersion            string    `json:"rules_version"`
	KnowledgeVersion        string    `json:"knowledge_version"`
	ClassRule               string    `json:"class_rule"`
	Weights                 epWeights `json:"weights"`
	Agents                  []epAgent `json:"agents"`
}

func epAxisOf(a exposure.Axis) epAxis {
	if a.Level == nil {
		return epAxis{Level: nil, NoData: a.NoData}
	}
	inputs := a.Inputs
	if len(inputs) == 0 {
		inputs = nil
	}
	return epAxis{Level: a.Level, Inputs: inputs}
}

// exposurePotentialDoc builds the document from the nine agents' exposure
// potential (same order as factory-scores.json).
func exposurePotentialDoc(t *testing.T) exposurePotential {
	t.Helper()
	doc := exposurePotential{
		Format:            "exposure-potential.v1",
		RosmaropsVersion:  envOr("ROSMAROPS_VERSION", "dev"),
		Commit:            os.Getenv("GITHUB_SHA"),
		GeneratedAt:       time.Now().UTC().Format(time.RFC3339),
		ReferenceComputer: "R2",
		ContagionComputer: "R2-all",
		// D1: until CTO-25's Windows clean-install photos exist, R2-todos is
		// built from R2's own fixtures. Recorded here, not in prose.
		ContagionComputerSource: "r2_fixtures",
		RulesVersion:            graph.RulesVersion,
		KnowledgeVersion:        knowledge.Composite,
		ClassRule:               "weighted_v1",
		Weights: epWeights{
			Autonomy:   exposure.Weights[exposure.AxisAutonomy],
			Reach:      exposure.Weights[exposure.AxisReach],
			Contagion:  exposure.Weights[exposure.AxisContagion],
			Delegation: exposure.Weights[exposure.AxisDelegation],
			Opacity:    exposure.Weights[exposure.AxisOpacity],
			Complexity: exposure.Weights[exposure.AxisComplexity],
		},
	}
	for _, a := range r2ExposureAgents(t) {
		missing := a.MissingAxes
		if missing == nil {
			missing = []string{}
		}
		doc.Agents = append(doc.Agents, epAgent{
			Product:   a.Product,
			Evaluated: a.Evaluated,
			Axes: epAxes{
				Autonomy:   epAxisOf(a.Axes[exposure.AxisAutonomy]),
				Reach:      epAxisOf(a.Axes[exposure.AxisReach]),
				Contagion:  epAxisOf(a.Axes[exposure.AxisContagion]),
				Delegation: epAxisOf(a.Axes[exposure.AxisDelegation]),
				Opacity:    epAxisOf(a.Axes[exposure.AxisOpacity]),
				Complexity: epAxisOf(a.Axes[exposure.AxisComplexity]),
			},
			Class:       a.Class,
			ClassStatus: a.ClassStatus,
			MissingAxes: missing,
			FactoryBand: a.FactoryBand,
		})
	}
	return doc
}

// TestExposurePotential writes exposure-potential.json to the absolute path in
// ROSMAROPS_EXPOSURE_POTENTIAL_OUT (release.yml sets it next to
// factory-scores.json). With no variable nothing is written; the binary is
// untouched (BV-200 pattern).
func TestExposurePotential(t *testing.T) {
	doc := exposurePotentialDoc(t)
	out := os.Getenv("ROSMAROPS_EXPOSURE_POTENTIAL_OUT")
	if out == "" {
		return
	}
	if !filepath.IsAbs(out) {
		t.Fatalf("ROSMAROPS_EXPOSURE_POTENTIAL_OUT must be an absolute path, got %q: go test runs in the package directory", out)
	}
	data, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	data = append(data, '\n')
	if err := os.WriteFile(out, data, 0o644); err != nil {
		t.Fatalf("write %s: %v", out, err)
	}
	t.Logf("wrote exposure-potential to %s (%d bytes)", out, len(data))
}

// TestExposurePotentialJSON validates the document: nine agents, the v1 format
// tag, every axis present, and no value carrying catalog prose (no string value
// has a space, so no sentence slipped in).
func TestExposurePotentialJSON(t *testing.T) {
	doc := exposurePotentialDoc(t)
	if doc.Format != "exposure-potential.v1" || doc.ReferenceComputer != "R2" {
		t.Errorf("format/reference: %q / %q", doc.Format, doc.ReferenceComputer)
	}
	if doc.ContagionComputerSource != "r2_fixtures" {
		t.Errorf("contagion_computer_source = %q, want r2_fixtures (D1)", doc.ContagionComputerSource)
	}
	if len(doc.Agents) != 9 {
		t.Fatalf("want 9 agents, got %d", len(doc.Agents))
	}
	for _, a := range doc.Agents {
		// CTO-31 M1: while the registry is not complete, complexity has no data
		// and the class can only be provisional, with complexity among the
		// missing axes. A «final» class here would claim a complexity the engine
		// does not know.
		if a.Axes.Complexity.Level == nil {
			if a.ClassStatus != "provisional" {
				t.Errorf("%s: complexity has no data but class_status is %q, want provisional", a.Product, a.ClassStatus)
			}
			found := false
			for _, m := range a.MissingAxes {
				found = found || m == "complexity"
			}
			if !found {
				t.Errorf("%s: complexity has no data but missing_axes = %v", a.Product, a.MissingAxes)
			}
		}
		for name, ax := range map[string]epAxis{
			"autonomy": a.Axes.Autonomy, "reach": a.Axes.Reach, "contagion": a.Axes.Contagion,
			"delegation": a.Axes.Delegation, "opacity": a.Axes.Opacity, "complexity": a.Axes.Complexity,
		} {
			if ax.Level == nil && ax.NoData == "" {
				t.Errorf("%s axis %s: no level and no no_data", a.Product, name)
			}
			if ax.Level != nil && ax.NoData != "" {
				t.Errorf("%s axis %s: both level and no_data", a.Product, name)
			}
		}
	}
	data, err := json.MarshalIndent(doc, "", "  ")
	if err != nil {
		t.Fatal(err)
	}
	var generic any
	if err := json.Unmarshal(data, &generic); err != nil {
		t.Fatal(err)
	}
	walkStrings(generic, func(v string) {
		if strings.ContainsRune(v, ' ') {
			t.Errorf("exposure-potential value contains a space (possible prose): %q", v)
		}
	})
}

// TestExposureNotEvaluatedJSON (CTO-31 M3 i): a detected-only agent, written
// with the file's own shape, carries no class and no class_status key; its
// axes are opacity 3 and the rest null with not_evaluated.
func TestExposureNotEvaluatedJSON(t *testing.T) {
	a := exposure.Compute(exposure.Inputs{Product: "cursor", Evaluated: false, FactoryBand: "exposed"})
	missing := a.MissingAxes
	if missing == nil {
		missing = []string{}
	}
	ag := epAgent{
		Product: a.Product, Evaluated: a.Evaluated,
		Axes: epAxes{
			Autonomy: epAxisOf(a.Axes[exposure.AxisAutonomy]), Reach: epAxisOf(a.Axes[exposure.AxisReach]),
			Contagion: epAxisOf(a.Axes[exposure.AxisContagion]), Delegation: epAxisOf(a.Axes[exposure.AxisDelegation]),
			Opacity: epAxisOf(a.Axes[exposure.AxisOpacity]), Complexity: epAxisOf(a.Axes[exposure.AxisComplexity]),
		},
		Class: a.Class, ClassStatus: a.ClassStatus, MissingAxes: missing, FactoryBand: a.FactoryBand,
	}
	data, err := json.Marshal(ag)
	if err != nil {
		t.Fatal(err)
	}
	var m map[string]any
	if err := json.Unmarshal(data, &m); err != nil {
		t.Fatal(err)
	}
	for _, k := range []string{"class", "class_status"} {
		if _, ok := m[k]; ok {
			t.Errorf("not-evaluated agent JSON has %q: %s", k, data)
		}
	}
	axes := m["axes"].(map[string]any)
	for name, v := range axes {
		ax := v.(map[string]any)
		if name == "opacity" {
			if ax["level"] != float64(3) {
				t.Errorf("opacity level = %v, want 3", ax["level"])
			}
			continue
		}
		if ax["level"] != nil || ax["no_data"] != "not_evaluated" {
			t.Errorf("%s = %v, want level null and not_evaluated", name, ax)
		}
	}
}
